"""{NAME} ({ID}): current step in NEURON. Generated by hippsim (Neurons → Simulate → Run it in → NEURON).
Needs: pip install neuron matplotlib, and {SWC_FILE} next to this script.
Model (same as hippsim's browser engine and the Brian2 script): the reconstruction with leak Rm 20 kΩ·cm²,
Ra 150 Ω·cm, Cm 1 µF/cm² and Hodgkin–Huxley Na/K at 6.3 °C (gNa 0.5, gK 0.1 S/cm² in soma and axon, a fraction
of that in dendrites). A starting point to edit, not a fitted model."""
from neuron import h
import matplotlib.pyplot as plt

# ---- settings (from hippsim; edit freely) ----
AMP = {AMP_NA}          # nA, 300 ms step starting at 50 ms
NA_SCALE = {NA_SCALE}     # × gNa 0.5 S/cm²
K_SCALE = {K_SCALE}      # × gK 0.1 S/cm²
DEND = {DEND_FRAC}       # dendritic channel density, fraction of soma
SITE = {SITE_XYZ}       # electrode: None = soma, or (x, y, z) in the SWC's µm coordinates ({SITE_LABEL})

def clean_swc(src, dst):
    """Drop points that sit exactly on their parent (re-parent their children): zero-length sections break the cable
    equation. Radii below 0.05 µm (tracing artefacts) become 0.05 µm. Same cleaning as the Brian2 script."""
    rows = {}
    for line in open(src):
        if line.strip() and not line.startswith("#"):
            i, t, x, y, z, rad, p = line.split()[:7]; rows[int(i)] = [int(t), float(x), float(y), float(z), max(float(rad), 0.05), int(p)]
    alias = {}
    for i, (t, x, y, z, rad, p) in rows.items():
        p = alias.get(p, p)
        if p in rows and t != 1 and (x, y, z) == tuple(rows[p][1:4]): alias[i] = p
        rows[i][5] = p
    with open(dst, "w") as f:
        for i, (t, x, y, z, rad, p) in rows.items():
            if i not in alias: f.write(f"{i} {t} {x} {y} {z} {rad} {p}\n")
    return dst

h.load_file("stdrun.hoc"); h.load_file("import3d.hoc")
r = h.Import3d_SWC_read(); r.input(clean_swc("{SWC_FILE}", "neuron_{SWC_FILE}"))
h.Import3d_GUI(r, False).instantiate(None)
soma = h.soma[0]
for s in h.allsec():
    s.cm = 1; s.Ra = 150
    s.nseg = 1 if s.L < 1e-3 else int((s.L / (0.1 * h.lambda_f(100, sec=s)) + 0.9) / 2) * 2 + 1   # d_lambda = 0.1
    s.insert("hh")
    f = 1.0 if s.name().startswith(("soma", "axon")) else DEND
    for seg in s:
        seg.hh.gnabar, seg.hh.gkbar, seg.hh.gl, seg.hh.el = 0.5 * NA_SCALE * f, 0.1 * K_SCALE * f, 1 / 20000, -65

def nearest(xyz):
    best = (1e18, soma, 0.5)
    for s in h.allsec():
        for i in range(s.n3d()):
            d = (s.x3d(i) - xyz[0]) ** 2 + (s.y3d(i) - xyz[1]) ** 2 + (s.z3d(i) - xyz[2]) ** 2
            if d < best[0]: best = (d, s, s.arc3d(i) / s.L if s.L else 0.5)
    return best[1](min(max(best[2], 0), 1))

site = soma(0.5) if SITE is None else nearest(SITE)
stim = h.IClamp(site); stim.delay, stim.dur, stim.amp = 50, 300, AMP
t, v, ve = h.Vector().record(h._ref_t), h.Vector().record(soma(0.5)._ref_v), h.Vector().record(site._ref_v)
h.celsius = 6.3; h.finitialize(-65); h.dt = 0.025; h.continuerun(400)

tt, vv = list(t), list(v)
spk = [tt[i + 1] for i in range(len(vv) - 1) if vv[i] < 0 <= vv[i + 1] and 50 <= tt[i + 1] < 350]
print(f"RESULT engine=NEURON spikes={len(spk)} first_ms={spk[0] - 50 if spk else 'none'}")
import os
if os.environ.get("HIPPSIM_TRACE"):                              # used by hippsim's engine check (soma V every 0.5 ms)
    print("TRACE", [round(vv[i], 1) for i in range(0, len(vv), 20)])
print(f"{NAME}: {len(spk)} spikes during a {AMP} nA, 300 ms step at {'the soma' if SITE is None else site}")
plt.plot(t, v, lw=0.8, label="soma")
if SITE is not None: plt.plot(t, ve, lw=0.8, label="electrode")
plt.xlabel("time (ms)"); plt.ylabel("V (mV)"); plt.title("{NAME} ({ID}) · NEURON"); plt.legend(); plt.show()
